from pylint.lint import PyLintChecker, Run
from io import StringIO

class ADAMCodeQualityAuditor:
    def __init__(self):
        self.pylint_output = None

    def audit_code(self, file_path):
        """Audit the quality of the code in the given file using pylint."""
        pylint_stdout = StringIO()
        run = Run([file_path], reporter=PyLintChecker(output=pylint_stdout), do_exit=False)
        self.pylint_output = pylint_stdout.getvalue()
        return self.pylint_output

    def get_score(self):
        """Extract and return the score from the pylint output."""
        if self.pylint_output is not None:
            for line in reversed(self.pylint_output.splitlines()):
                if 'Your code has been rated at' in line:
                    score_str = line.split('rated at')[1].split('/')[0].strip()
                    return float(score_str)
        return None

