def audit_service_config(service_configs):
    # Initialisation de la liste des configurations non sécurisées
    insecure_configs = []

    # Règles de sécurité pour chaque type de configuration
    security_rules = {
        'database': {'encryption': True, 'latest_version': True},
        'api_gateway': {'ssl_enabled': True, 'rate_limiting': True},
        'storage': {'encryption_at_rest': True, 'version_control': True}
    }

    # Vérification de chaque configuration
    for config in service_configs:
        service_type = config['type']
        if service_type not in security_rules:
            continue
        for rule_key, rule_value in security_rules[service_type].items():
            if config.get(rule_key) != rule_value:
                insecure_configs.append(config)
                break

    return insecure_configs

